export interface Recipient {
  name: string;
  postalAddress: string;
}

export interface ProviderRequest {
  shipmentId: string;
  routeCode: string;
  parcelGrams: number;
  recipient: Recipient;
  idempotencyKey: string;
}

export interface ShippingDependencies {
  repository: {
    get(shipmentId: string): Promise<unknown>;
    save(shipmentId: string, record: unknown): Promise<void>;
  };
  atlas: {
    book(request: ProviderRequest): Promise<unknown>;
  };
  beacon: {
    reserve(request: ProviderRequest): Promise<unknown>;
  };
  logger: {
    info(event: Record<string, unknown>): void;
  };
}

type Provider = "atlas" | "beacon";
type RefusalReason = "unsupported_route" | "unsupported_parcel";

interface Rejection {
  provider: Provider;
  reason: RefusalReason;
}

interface ShipmentFields {
  schemaVersion: 1;
  id: string;
  routeCode: string;
  parcelGrams: number;
}

interface QueuedShipment extends ShipmentFields {
  state: "queued";
}

interface DispatchedShipment extends ShipmentFields {
  state: "dispatched";
  provider: Provider;
  bookingId: string;
  dispatchedAtMs: number;
}

interface DeferredShipment extends ShipmentFields {
  state: "deferred";
  nextProvider: Provider;
  retryAtMs: number;
  rejections: Rejection[];
}

interface UnavailableShipment extends ShipmentFields {
  state: "unavailable";
  rejections: Rejection[];
}

type StoredShipment = QueuedShipment | DispatchedShipment | DeferredShipment | UnavailableShipment;
export type PublicShipment =
  | Omit<QueuedShipment, "schemaVersion">
  | Omit<DispatchedShipment, "schemaVersion">
  | Omit<DeferredShipment, "schemaVersion">
  | Omit<UnavailableShipment, "schemaVersion">;

interface AbortBody {
  code: "dispatch_aborted";
  shipmentId: string;
  failedAt: Provider | "repository";
  classification: "unknown_failure" | "invalid_provider_response" | "repository_failure";
  rejections: Rejection[];
}

export interface ServiceResponse {
  status: number;
  body: PublicShipment | AbortBody | {
    code: "invalid_command" | "not_found";
  };
}

type Command =
  | { op: "get"; shipmentId: string }
  | { op: "dispatch"; shipmentId: string; nowMs: number; recipient: Recipient };

function isObject(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}

function parseCommand(value: unknown): Command | undefined {
  if (!isObject(value) || typeof value.shipmentId !== "string" || value.shipmentId.length === 0) {
    return undefined;
  }
  if (value.op === "get") {
    return { op: "get", shipmentId: value.shipmentId };
  }
  if (
    value.op !== "dispatch" ||
    typeof value.nowMs !== "number" ||
    !Number.isSafeInteger(value.nowMs) ||
    value.nowMs < 0 ||
    !isObject(value.recipient) ||
    typeof value.recipient.name !== "string" ||
    value.recipient.name.trim().length === 0 ||
    typeof value.recipient.postalAddress !== "string" ||
    value.recipient.postalAddress.trim().length === 0
  ) {
    return undefined;
  }
  return {
    op: "dispatch",
    shipmentId: value.shipmentId,
    nowMs: value.nowMs,
    recipient: {
      name: value.recipient.name,
      postalAddress: value.recipient.postalAddress,
    },
  };
}

function publicShipment(shipment: StoredShipment): PublicShipment {
  const fields = {
    id: shipment.id,
    routeCode: shipment.routeCode,
    parcelGrams: shipment.parcelGrams,
  };
  if (shipment.state === "queued") {
    return { ...fields, state: "queued" };
  }
  if (shipment.state === "dispatched") {
    return {
      ...fields,
      state: "dispatched",
      provider: shipment.provider,
      bookingId: shipment.bookingId,
      dispatchedAtMs: shipment.dispatchedAtMs,
    };
  }
  if (shipment.state === "deferred") {
    return {
      ...fields,
      state: "deferred",
      nextProvider: shipment.nextProvider,
      retryAtMs: shipment.retryAtMs,
      rejections: shipment.rejections.map(copyRejection),
    };
  }
  return {
    ...fields,
    state: "unavailable",
    rejections: shipment.rejections.map(copyRejection),
  };
}

function copyRejection(rejection: Rejection): Rejection {
  return { provider: rejection.provider, reason: rejection.reason };
}

function baseFields(shipment: StoredShipment): ShipmentFields {
  return {
    schemaVersion: 1,
    id: shipment.id,
    routeCode: shipment.routeCode,
    parcelGrams: shipment.parcelGrams,
  };
}

function requestFor(shipment: StoredShipment, recipient: Recipient): ProviderRequest {
  return {
    shipmentId: shipment.id,
    routeCode: shipment.routeCode,
    parcelGrams: shipment.parcelGrams,
    recipient: {
      name: recipient.name,
      postalAddress: recipient.postalAddress,
    },
    idempotencyKey: shipment.id,
  };
}

function isReason(value: unknown): value is RefusalReason {
  return value === "unsupported_route" || value === "unsupported_parcel";
}

type ProviderFailure =
  | { kind: "refusal"; reason: RefusalReason }
  | { kind: "throttle"; retryAtMs: number }
  | { kind: "invalid_provider_response" }
  | { kind: "unknown_failure" };

function classifyProviderRejection(provider: Provider, value: unknown, nowMs: number): ProviderFailure {
  if (!isObject(value)) {
    return { kind: "unknown_failure" };
  }
  if (provider === "atlas") {
    if (value.code === "cannot_ship") {
      return isReason(value.reason)
        ? { kind: "refusal", reason: value.reason }
        : { kind: "invalid_provider_response" };
    }
    if (value.code === "rate_limited") {
      const retryAtMs = value.retryAtMs;
      return typeof retryAtMs === "number" && Number.isSafeInteger(retryAtMs) && retryAtMs > nowMs
        ? { kind: "throttle", retryAtMs }
        : { kind: "invalid_provider_response" };
    }
    return { kind: "unknown_failure" };
  }

  if (value.type === "rejected") {
    return isObject(value.details) && isReason(value.details.reason)
      ? { kind: "refusal", reason: value.details.reason }
      : { kind: "invalid_provider_response" };
  }
  if (value.type === "throttled") {
    const retryAtMs = isObject(value.details) ? value.details.retryAtMs : undefined;
    return (
      typeof retryAtMs === "number" &&
      Number.isSafeInteger(retryAtMs) &&
      retryAtMs > nowMs
    )
      ? { kind: "throttle", retryAtMs }
      : { kind: "invalid_provider_response" };
  }
  return { kind: "unknown_failure" };
}

function readConfirmation(provider: Provider, value: unknown): string | undefined {
  if (!isObject(value)) {
    return undefined;
  }
  const identifier = provider === "atlas" ? value.bookingId : value.reference;
  return typeof identifier === "string" && identifier.length > 0 ? identifier : undefined;
}

function abortResponse(
  shipmentId: string,
  failedAt: Provider | "repository",
  classification: AbortBody["classification"],
  rejections: Rejection[],
): ServiceResponse {
  return {
    status: 500,
    body: {
      code: "dispatch_aborted",
      shipmentId,
      failedAt,
      classification,
      rejections: rejections.map(copyRejection),
    },
  };
}

export function createShippingService(dependencies: ShippingDependencies) {
  function emitAbort(body: AbortBody) {
    dependencies.logger.info({
      shipmentId: body.shipmentId,
      action: "aborted",
      failedAt: body.failedAt,
      classification: body.classification,
      rejections: body.rejections.map(copyRejection),
    });
  }

  async function saveDecision(
    shipmentId: string,
    record: StoredShipment,
    event: Record<string, unknown>,
    abortRejections: Rejection[],
  ): Promise<ServiceResponse | undefined> {
    try {
      await dependencies.repository.save(shipmentId, record);
    } catch {
      const response = abortResponse(
        shipmentId,
        "repository",
        "repository_failure",
        abortRejections,
      );
      emitAbort(response.body as AbortBody);
      return response;
    }
    dependencies.logger.info(event);
    return undefined;
  }

  async function attemptProvider(
    provider: Provider,
    shipment: StoredShipment,
    command: Extract<Command, { op: "dispatch" }>,
    rejections: Rejection[],
  ): Promise<ServiceResponse | { continueWithBeacon: Rejection[] }> {
    let confirmation: unknown;
    try {
      confirmation = provider === "atlas"
        ? await dependencies.atlas.book(requestFor(shipment, command.recipient))
        : await dependencies.beacon.reserve(requestFor(shipment, command.recipient));
    } catch (error) {
      const failure = classifyProviderRejection(provider, error, command.nowMs);
      if (failure.kind === "refusal") {
        const nextRejections = [...rejections, { provider, reason: failure.reason }];
        if (provider === "atlas") {
          return { continueWithBeacon: nextRejections };
        }
        const unavailable: UnavailableShipment = {
          ...baseFields(shipment),
          state: "unavailable",
          rejections: nextRejections.map(copyRejection),
        };
        const abort = await saveDecision(
          shipment.id,
          unavailable,
          {
            shipmentId: shipment.id,
            action: "unavailable",
            rejections: nextRejections.map(copyRejection),
          },
          nextRejections,
        );
        if (abort) {
          return abort;
        }
        return { status: 422, body: publicShipment(unavailable) };
      }
      if (failure.kind === "throttle") {
        const deferred: DeferredShipment = {
          ...baseFields(shipment),
          state: "deferred",
          nextProvider: provider,
          retryAtMs: failure.retryAtMs,
          rejections: rejections.map(copyRejection),
        };
        const abort = await saveDecision(
          shipment.id,
          deferred,
          {
            shipmentId: shipment.id,
            action: "deferred",
            provider,
            retryAtMs: failure.retryAtMs,
            rejections: rejections.map(copyRejection),
          },
          rejections,
        );
        if (abort) {
          return abort;
        }
        return { status: 202, body: publicShipment(deferred) };
      }
      const response = abortResponse(shipment.id, provider, failure.kind, rejections);
      emitAbort(response.body as AbortBody);
      return response;
    }

    const bookingId = readConfirmation(provider, confirmation);
    if (!bookingId) {
      const response = abortResponse(
        shipment.id,
        provider,
        "invalid_provider_response",
        rejections,
      );
      emitAbort(response.body as AbortBody);
      return response;
    }

    const dispatched: DispatchedShipment = {
      ...baseFields(shipment),
      state: "dispatched",
      provider,
      bookingId,
      dispatchedAtMs: command.nowMs,
    };
    const abort = await saveDecision(
      shipment.id,
      dispatched,
      {
        shipmentId: shipment.id,
        action: "dispatched",
        provider,
      },
      rejections,
    );
    if (abort) {
      return abort;
    }
    return { status: 200, body: publicShipment(dispatched) };
  }

  async function handle(input: unknown): Promise<ServiceResponse> {
    const command = parseCommand(input);
    if (!command) {
      return { status: 400, body: { code: "invalid_command" } };
    }

    let value: unknown;
    try {
      value = await dependencies.repository.get(command.shipmentId);
    } catch {
      const response = abortResponse(
        command.shipmentId,
        "repository",
        "repository_failure",
        [],
      );
      emitAbort(response.body as AbortBody);
      return response;
    }
    if (value === undefined) {
      return { status: 404, body: { code: "not_found" } };
    }

    // Storage contains the host's queued records or this service's own saved JSON.
    const shipment = value as StoredShipment;
    if (command.op === "get") {
      return { status: 200, body: publicShipment(shipment) };
    }
    if (shipment.state === "dispatched") {
      return { status: 200, body: publicShipment(shipment) };
    }
    if (shipment.state === "unavailable") {
      return { status: 422, body: publicShipment(shipment) };
    }
    if (shipment.state === "deferred" && command.nowMs < shipment.retryAtMs) {
      return { status: 202, body: publicShipment(shipment) };
    }

    const firstProvider = shipment.state === "deferred" ? shipment.nextProvider : "atlas";
    const rejections = shipment.state === "deferred"
      ? shipment.rejections.map(copyRejection)
      : [];
    const firstResult = await attemptProvider(firstProvider, shipment, command, rejections);
    if ("continueWithBeacon" in firstResult) {
      const secondResult = await attemptProvider(
        "beacon",
        shipment,
        command,
        firstResult.continueWithBeacon,
      );
      if ("continueWithBeacon" in secondResult) {
        const response = abortResponse(
          shipment.id,
          "beacon",
          "invalid_provider_response",
          secondResult.continueWithBeacon,
        );
        emitAbort(response.body as AbortBody);
        return response;
      }
      return secondResult;
    }
    return firstResult;
  }

  return { handle };
}
